using System;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Collections;using System.Collections.Generic;
sealed class ImageTextWindow:Form {
 readonly Bitmap image;readonly PictureBox canvas=new PictureBox{Dock=DockStyle.Fill,SizeMode=PictureBoxSizeMode.Zoom};readonly RichTextBox transcript=new RichTextBox{Dock=DockStyle.Bottom,Height=110,ReadOnly=true};readonly Label status=new Label{Dock=DockStyle.Bottom,Height=38};readonly List<OcrWord> words=new List<OcrWord>();int start=-1,end=-1;bool selecting;int sourceWidth,sourceHeight;internal bool Ready;internal void SelectWordsForCheck(int first,int last){start=first;end=last;canvas.Invalidate();}internal string SelectedWords{get{int first=Math.Min(start,end),last=Math.Max(start,end);if(first<0||last>=words.Count)return "";string result="";int line=-1;for(int i=first;i<=last;i++){result+=(i==first?"":words[i].Line!=line?Environment.NewLine:" ")+words[i].Text;line=words[i].Line;}return result;}}
 internal ImageTextWindow(Bitmap source,Companion owner){image=new Bitmap(source);Text="Select text from image · offline";Size=new Size(900,700);MinimumSize=new Size(500,400);Font=owner.Font;Icon=owner.Icon;canvas.Image=image;var row=new FlowLayoutPanel{Dock=DockStyle.Top,Height=42};var copy=new Button{Text="Copy selected words",AutoSize=true};copy.Click+=(s,e)=>Copy();var all=new Button{Text="Copy all text",AutoSize=true};all.Click+=(s,e)=>{if(transcript.TextLength>0)Clipboard.SetText(transcript.Text);};var retry=new Button{Text="Recognise text again",AutoSize=true};row.Controls.Add(copy);row.Controls.Add(all);row.Controls.Add(retry);Controls.Add(canvas);Controls.Add(transcript);Controls.Add(status);Controls.Add(row);owner.ThemeControls(this);status.Text="Recognising locally with Windows…";canvas.Cursor=Cursors.IBeam;var menu=new ContextMenuStrip();menu.Items.Add("Copy selected words",null,(s,e)=>Copy());menu.Items.Add("Copy all text",null,(s,e)=>{if(transcript.TextLength>0)Clipboard.SetText(transcript.Text);});menu.Items.Add("Select all words",null,(s,e)=>{start=0;end=words.Count-1;canvas.Invalidate();});canvas.ContextMenuStrip=menu;owner.ThemeMenu(menu);FormClosed+=(s,e)=>menu.Dispose();canvas.MouseDown+=(s,e)=>{if(e.Button!=MouseButtons.Left)return;start=end=Hit(e.Location);selecting=start>=0;canvas.Capture=selecting;canvas.Invalidate();};canvas.MouseMove+=(s,e)=>{if(!selecting)return;int next=Hit(e.Location);if(next>=0){end=next;canvas.Invalidate();}};canvas.MouseUp+=(s,e)=>{selecting=false;canvas.Capture=false;};canvas.Paint+=(s,e)=>{Rectangle box=ImageBox();using(var fill=new SolidBrush(Color.FromArgb(100,SystemColors.Highlight)))using(var pen=new Pen(SystemColors.Highlight)){for(int i=0;i<words.Count;i++){var w=words[i];var r=new RectangleF(box.X+w.Box.X*box.Width/sourceWidth,box.Y+w.Box.Y*box.Height/sourceHeight,w.Box.Width*box.Width/sourceWidth,w.Box.Height*box.Height/sourceHeight);if(start>=0&&i>=Math.Min(start,end)&&i<=Math.Max(start,end))e.Graphics.FillRectangle(fill,r);else e.Graphics.DrawRectangle(pen,r.X,r.Y,r.Width,r.Height);}}};KeyPreview=true;KeyDown+=(s,e)=>{if(e.Control&&e.KeyCode==Keys.C){Copy();e.SuppressKeyPress=true;}if(e.Control&&e.KeyCode==Keys.A){start=0;end=words.Count-1;canvas.Invalidate();e.SuppressKeyPress=true;}};FormClosed+=(s,e)=>{canvas.Image=null;image.Dispose();};retry.Click+=async(s,e)=>{retry.Enabled=false;try{await Recognise();}finally{if(!IsDisposed)retry.Enabled=true;}};Shown+=async(s,e)=>{retry.Enabled=false;try{await Recognise();}finally{if(!IsDisposed)retry.Enabled=true;}};}
 async System.Threading.Tasks.Task Recognise(){try{using(var copy=new Bitmap(image)){var result=await OfflineImageText.Recognise(copy);if(IsDisposed)return;words.Clear();sourceWidth=Convert.ToInt32(result["width"]);sourceHeight=Convert.ToInt32(result["height"]);foreach(Dictionary<string,object> word in (IEnumerable)result["words"])words.Add(new OcrWord{Text=Convert.ToString(word["text"]),Line=Convert.ToInt32(word["line"]),Box=new RectangleF(Convert.ToSingle(word["x"]),Convert.ToSingle(word["y"]),Convert.ToSingle(word["w"]),Convert.ToSingle(word["h"]))});transcript.Text=Convert.ToString(result["text"]);status.Text=words.Count==0?"No words found. Try a clearer image.":"Drag across outlined words, then Ctrl+C · "+result["language"]+" · Nothing uploads";start=end=-1;canvas.Invalidate();Ready=true;}}catch(Exception error){if(!IsDisposed)status.Text=error.Message;}}
 Rectangle ImageBox(){float scale=Math.Min(canvas.ClientSize.Width/(float)image.Width,canvas.ClientSize.Height/(float)image.Height);int w=(int)(image.Width*scale),h=(int)(image.Height*scale);return new Rectangle((canvas.Width-w)/2,(canvas.Height-h)/2,w,h);}
 int Hit(Point point){if(sourceWidth==0)return -1;Rectangle box=ImageBox();float x=(point.X-box.X)*sourceWidth/(float)box.Width,y=(point.Y-box.Y)*sourceHeight/(float)box.Height;for(int i=0;i<words.Count;i++)if(words[i].Box.Contains(x,y))return i;return -1;}
 void Copy(){string text=transcript.Focused&&transcript.SelectionLength>0?transcript.SelectedText:SelectedWords;if(text.Length>0)Clipboard.SetText(text);}
 sealed class OcrWord{internal string Text;internal int Line;internal RectangleF Box;}
}
